#include "opensim/server/poll_request.hpp"
#include <iostream>
#include <sstream>
#include <limits>
using namespace opensim;using namespace server;
namespace {
std::string hex(const std::string& s){const char* h="0123456789abcdef";std::string r;for(unsigned char c:s){r+=h[c>>4];r+=h[c&15];}return r;}
std::string unhex(const std::string& s){std::string r;for(size_t i=0;i<s.size();i+=2)r+=char(std::stoi(s.substr(i,2),nullptr,16));return r;}
struct State {std::string trace,fail;void event(std::string s){trace+=s+";";if(s==fail)throw std::runtime_error("injected");}};
struct Body:PollBody{State& s;Body(State& x):s(x){}bool can_read()const override{s.event("read");return true;}void dispose()override{s.event("dispose");}};
struct Incoming:PollIncomingRequest{State& s;std::shared_ptr<Body> b;Incoming(State& x):s(x),b(std::make_shared<Body>(x)){}std::shared_ptr<PollBody> body()const override{s.event("body");return b;}std::shared_ptr<PollContext> context()const override{return {};}};
struct Response:PollResponse{State& s;Response(State& x):s(x){}void status_code(int32_t v)override{s.event("status:"+std::to_string(v));}void content_length(int64_t v)override{s.event("length:"+std::to_string(v));}void utf8_encoding()override{s.event("utf8");}void keep_alive(bool v)override{s.event(v?"keep:1":"keep:0");}void keep_alive_timeout(int32_t v)override{s.event("timeout:"+std::to_string(v));}void protocol_version(PollName)override{}void status_description(PollName)override{}void add_header(const std::string& k,PollName v)override{s.event("header:"+k+":"+(v?hex(*v):"N"));}void redirect(PollName v,int32_t)override{s.event("redirect:"+(v?hex(*v):"N"));}void buffer_start(int32_t v)override{s.event("start:"+std::to_string(v));}void buffer_length(int32_t v)override{s.event("count:"+std::to_string(v));}void buffer(PollBytes v)override{s.event("buffer:"+hex(std::string(v->begin(),v->end())));}void send()override{s.event("send");}};
struct Backend:PollRequestBackend{State& s;Backend(State& x):s(x){}PollResponsePtr make_response(const std::shared_ptr<PollIncomingRequest>&)override{s.event("factory");return std::make_shared<Response>(s);}void warn(const std::string&,const std::exception&)override{s.event("warn");}};
}
int main(){std::string line;while(std::getline(std::cin,line)){std::vector<std::string> a;std::stringstream input(line);std::string field;while(std::getline(input,field,'|'))a.push_back(field);State s;s.fail=a.at(7);Backend backend(s);auto args=std::make_shared<services::CapabilityPollHandler>();args->requests_handled=std::stoi(a.at(9));auto incoming=std::make_shared<Incoming>(s);PollServiceHttpRequest request(args,incoming,backend);auto data=std::make_shared<PollTable>();if(a[1]!="N")data->set("content_type",unhex(a[1]));data->set("str_response_string",unhex(a[2]));data->set("int_response_code",std::int32_t(std::stoi(a[6])));if(a[8]=="long")data->set("int_response_code",std::int64_t(200));if(a[0]=="binary"){auto bytes=std::make_shared<std::vector<uint8_t>>(std::initializer_list<uint8_t>{0,1,2,253,254,255});data->set("bin_response_data",bytes);data->set("bin_start",std::int32_t(std::stoi(a[3])));data->set("int_bytes",std::int32_t(std::stoi(a[4])));}if(a[0]=="prefab")data->set("h",PollResponsePtr(std::make_shared<Response>(s)));if(a[0]=="nullprefab")data->set("h",{});if(a[0]=="badprefab")data->set("h",std::int32_t(4));data->set("str_redirect_location",std::string("/next"));bool error=false;try{if(a[0]=="stop")request.do_http_stop();else request.do_http_grunt_work(a[0]=="null"?nullptr:data);}catch(...){error=true;}std::cout<<s.trace<<"error:"<<error<<";handled:"<<std::int32_t(args->requests_handled)<<";consumed:"<<(a[0]=="binary"&&poll_object_null(data->get("bin_response_data")))<<'\n';}}
